-- Preserve custom permission subsets; normalize former full-role arrays to the role default.
UPDATE warehouse.users SET permissions=NULL WHERE role='admin' AND permissions @> '["workspace.read","portfolio.write","leases.write","tickets.write","billing.write","equipment.write","plans.write","maintenance.write","services.write","estimates.write","estimates.approve","meters.write","news.write","expenses.write","users.manage","permissions.manage","audit.read","imports.write"]'::jsonb AND '["workspace.read","portfolio.write","leases.write","tickets.write","billing.write","equipment.write","plans.write","maintenance.write","services.write","estimates.write","estimates.approve","meters.write","news.write","expenses.write","users.manage","permissions.manage","audit.read","imports.write"]'::jsonb @> permissions;
UPDATE warehouse.users SET permissions=NULL WHERE role='manager' AND permissions @> '["workspace.read","portfolio.write","leases.write","tickets.write","billing.write","equipment.write","plans.write","maintenance.write","services.write","estimates.write","estimates.approve","meters.write","news.write","expenses.write","users.manage","imports.write"]'::jsonb AND '["workspace.read","portfolio.write","leases.write","tickets.write","billing.write","equipment.write","plans.write","maintenance.write","services.write","estimates.write","estimates.approve","meters.write","news.write","expenses.write","users.manage","imports.write"]'::jsonb @> permissions;
UPDATE warehouse.users SET permissions=NULL WHERE role='worker' AND permissions @> '["workspace.read","tickets.write","meters.write"]'::jsonb AND '["workspace.read","tickets.write","meters.write"]'::jsonb @> permissions;
UPDATE warehouse.users SET permissions=NULL WHERE role='tenant' AND permissions @> '["workspace.read","tickets.write"]'::jsonb AND '["workspace.read","tickets.write"]'::jsonb @> permissions;
-- Convert existing account bindings to explicit scoped grants, preserving access and history.
INSERT INTO warehouse.user_assignments(id,user_id,business_role,scope_type,scope_id,permissions,valid_from,valid_to,retain_history,origin,reason,created_at,updated_at)
SELECT md5('staff:'||u.id),u.id,u.role,'property',u.property_id,
 CASE u.role WHEN 'manager' THEN '["finance.read","readings.submit","readings.review","work.approve","tickets.accept","documents.read","documents.write","workspace.read","portfolio.write","leases.write","tickets.write","billing.write","equipment.write","plans.write","maintenance.write","services.write","estimates.write","estimates.approve","meters.write","news.write","expenses.write","users.manage","imports.write"]'::jsonb ELSE '["workspace.read","tickets.write","meters.write","readings.submit","documents.read"]'::jsonb END,
 COALESCE(u.created_at::date,CURRENT_DATE),NULL,true,'staff_record','Миграция назначения сотрудника',now(),now()
FROM warehouse.users u WHERE u.role IN ('manager','worker') AND u.property_id IS NOT NULL;
INSERT INTO warehouse.user_assignments(id,user_id,business_role,scope_type,scope_id,permissions,valid_from,valid_to,retain_history,origin,reason,created_at,updated_at)
SELECT md5('lease:'||u.id||':'||l.id),u.id,'tenant','lease',l.id,'["workspace.read","tickets.write","finance.read","readings.submit","work.approve","tickets.accept","documents.read"]'::jsonb,l.start_date,l.end_date,true,'lease_record','Миграция доступа участника договора',now(),now()
FROM warehouse.users u JOIN warehouse.leases l ON l.tenant_id=u.tenant_id WHERE u.role='tenant';
